# Code generated by Claude
"""
Test that the generated robot file (models/robot/combined_robot.xml, from tools/import_openarm_description.py) matches the updated robot description it was made from.

    python experiments/robot_vs_urdf_test.py

The numbers of the expanded URDF (enactic/openarm_description 1fba2cb with Luke-kC/mobile_bimanual_ros2 74ce18e's pedestal_openarm) are in models/robot/openarm_v1_reference.json, written
by the import script. The compiled model (the bare robot file, no load-time additions) is compared with them:

1. Frames: every arm link, the hand, the tool point and the fingers sit where the URDF's joint chain puts them (torso frame, pedestal collapsed), and for 200 random joint vectors the tool
   point of each arm agrees with a forward kinematics of the URDF's chain (this checks the axes, the origins and the order together).
2. Joints: axes, ranges (arm joints, finger joints 0 to 0.044, pedestal 0 to 0.418); one slide joint for the pedestal; the second finger of each hand follows the first (a joint equality);
   one gripper actuator per hand and no second finger actuator.
3. Masses, centres of mass and inertia tensors of every arm link, hand and finger equal the URDF's (the fingers' tensor is not physical in the URDF, so for it the check is that MuJoCo's
   corrected moments differ by less than 3e-6 kg m^2, and the number is printed).
4. Meshes: every collision mesh's vertices, placed with the URDF's origin and scale, are where the model's geoms put them: including the mirrored meshes (the left arm's links and the
   "right_finger" of both hands, URDF scale y = -0.001). The torso's collision geom is deliberately the narrow post, not the URDF's whole-torso mesh (printed).
5. The pedestal: the torso is 0.3048 m above the pedestal base collapsed and 0.7228 m raised; the model starts raised; the masses are the old estimates (16.1868 kg fixed, 30.0476 kg moving).
"""

import json
import math
import struct
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

REF = json.loads((PROJECT_ROOT / "models/robot/openarm_v1_reference.json").read_text())
MODEL = PROJECT_ROOT / "models/robot/combined_robot.xml"
ASSETS = PROJECT_ROOT / "deps/OpenArm-Combined/assets/openarm/collision"
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def rpy_mat(rpy):
    r, p, y = rpy
    Rx = np.array([[1, 0, 0], [0, math.cos(r), -math.sin(r)], [0, math.sin(r), math.cos(r)]])
    Ry = np.array([[math.cos(p), 0, math.sin(p)], [0, 1, 0], [-math.sin(p), 0, math.cos(p)]])
    Rz = np.array([[math.cos(y), -math.sin(y), 0], [math.sin(y), math.cos(y), 0], [0, 0, 1]])
    return Rz @ Ry @ Rx


def axis_mat(ax, q):
    ax = np.asarray(ax, float)
    K = np.array([[0, -ax[2], ax[1]], [ax[2], 0, -ax[0]], [-ax[1], ax[0], 0]])
    return np.eye(3) + math.sin(q) * K + (1 - math.cos(q)) * K @ K


def load_stl(path):
    b = Path(path).read_bytes()
    if b[:5] == b"solid" and b"facet" in b[:400]:
        v = np.array([[float(x) for x in l.split()[1:]] for l in b.decode().splitlines() if l.strip().startswith("vertex")])
    else:
        n = struct.unpack("<I", b[80:84])[0]
        a = np.frombuffer(b[84:84 + 50 * n], dtype=np.dtype([("n", "<f4", 3), ("v", "<f4", (3, 3)), ("a", "<u2")]))
        v = a["v"].reshape(-1, 3).astype(float)
    return np.unique(np.round(v, 6), axis=0)


def stl_path(link_key):
    name = link_key.split("_", 2)[2]                       # e.g. link3, hand, right_finger
    if name.startswith("link"):
        return ASSETS / "arm" / f"{name}.stl"
    return ASSETS / "gripper" / ("hand.stl" if name == "hand" else "finger.stl")


def urdf_chain(side, q):
    """URDF forward kinematics of the arm: rotation and position of each link in the torso frame, and of the tool point."""
    J = REF["joints"]
    T = {}
    j = J[f"openarm_{side}_link0"]
    R, p = rpy_mat(j["rpy"]), np.array(j["xyz"])
    T["link0"] = (R, p)
    for i in range(1, 8):
        j = J[f"openarm_{side}_joint{i}"]
        p = p + R @ np.array(j["xyz"])
        R = R @ rpy_mat(j["rpy"]) @ axis_mat(j["axis"], q[i - 1])
        T[f"link{i}"] = (R, p)
    hj, tj = J[f"openarm_{side}_hand_joint"], J[f"openarm_{side}_hand_tcp_joint"]
    ph = p + R @ np.array(hj["xyz"])
    T["hand"] = (R, ph)
    T["tcp"] = (R, ph + R @ np.array(tj["xyz"]))
    return T


def main():
    m = mujoco.MjModel.from_xml_path(str(MODEL))
    d = mujoco.MjData(m)
    torso = m.body("openarm_body_link0").id
    ped_adr = m.joint("pedestal_joint").qposadr[0]
    d.qpos[ped_adr] = 0.0
    mujoco.mj_forward(m, d)
    Rt, pt = d.xmat[torso].reshape(3, 3), d.xpos[torso].copy()
    local = lambda b: (Rt.T @ d.xmat[b].reshape(3, 3), Rt.T @ (d.xpos[b] - pt))

    print("1. frames")
    for side in ("left", "right"):
        T = urdf_chain(side, np.zeros(7))
        err_p = err_r = 0.0
        for name, key in [(f"link{i}", f"link{i}") for i in range(8)] + [("hand", "hand"), ("hand_tcp", "tcp")]:
            R, p = local(m.body(f"openarm_{side}_{name}").id)
            err_p = max(err_p, np.abs(p - T[key][1]).max())
            err_r = max(err_r, np.abs(R - T[key][0]).max())
        check(f"{side}: link0 to link7, hand and tool point at q = 0 are at the URDF's poses", err_p < 1e-6 and err_r < 1e-6, f"position {err_p:.1e} m, rotation {err_r:.1e}")
        J = REF["joints"]
        ok_f = True
        for k, fname in ((1, "right_finger"), (2, "left_finger")):
            R, p = local(m.body(f"openarm_{side}_{fname}").id)
            fj = J[f"openarm_{side}_finger_joint{k}"]
            ok_f &= np.abs(p - (T["link7"][1] + T["link7"][0] @ np.array(fj["xyz"]))).max() < 1e-6
        check(f"{side}: both fingers sit at the URDF's finger joint origins (y = -0.005 and +0.005 from the hand's axis)", ok_f)
        rng = np.random.default_rng(3)
        lo = np.array([J[f"openarm_{side}_joint{i}"]["limit"][0] for i in range(1, 8)])
        hi = np.array([J[f"openarm_{side}_joint{i}"]["limit"][1] for i in range(1, 8)])
        adr = [m.joint(f"openarm_{side}_joint{i}").qposadr[0] for i in range(1, 8)]
        worst = 0.0
        for _ in range(200):
            q = rng.uniform(lo, hi)
            d.qpos[adr] = q
            mujoco.mj_forward(m, d)
            Rt, pt = d.xmat[torso].reshape(3, 3), d.xpos[torso].copy()
            R, p = local(m.body(f"openarm_{side}_hand_tcp").id)
            T = urdf_chain(side, q)
            worst = max(worst, np.abs(p - T["tcp"][1]).max(), np.abs(R - T["tcp"][0]).max())
        d.qpos[adr] = 0
        mujoco.mj_forward(m, d)
        Rt, pt = d.xmat[torso].reshape(3, 3), d.xpos[torso].copy()
        check(f"{side}: the tool point agrees with the URDF's forward kinematics for 200 random joint vectors", worst < 1e-6, f"worst {worst:.1e}")

    print("\n2. joints and actuators")
    J = REF["joints"]
    for side in ("left", "right"):
        bad = []
        for i in range(1, 8):
            jm, ju = m.joint(f"openarm_{side}_joint{i}"), J[f"openarm_{side}_joint{i}"]
            if not (np.allclose(jm.axis, ju["axis"]) and np.allclose(jm.range, ju["limit"][:2], atol=1e-6)):
                bad.append(i)
        check(f"{side}: the seven arm joints' axes and ranges equal the URDF's", not bad, f"mismatch {bad}" if bad else "")
        fj = [m.joint(f"openarm_{side}_finger_joint{k}") for k in (1, 2)]
        check(f"{side}: finger joints are slides with axes (0 -1 0) and (0 1 0), range 0 to 0.044", all(j.type[0] == mujoco.mjtJoint.mjJNT_SLIDE for j in fj)
              and np.allclose(fj[0].axis, [0, -1, 0]) and np.allclose(fj[1].axis, [0, 1, 0]) and all(np.allclose(j.range, [0, 0.044]) for j in fj))
        eq = [i for i in range(m.neq) if m.eq_type[i] == mujoco.mjtEq.mjEQ_JOINT and {m.eq_obj1id[i], m.eq_obj2id[i]} == {fj[0].id, fj[1].id}]
        check(f"{side}: finger 2 follows finger 1 through a joint equality (1:1)", len(eq) == 1 and np.allclose(m.eq_data[eq[0]][:5], [0, 1, 0, 0, 0]), f"data {m.eq_data[eq[0]][:5] if eq else None}")
        names = [m.actuator(i).name for i in range(m.nu)]
        check(f"{side}: one gripper actuator on finger_joint1 and no separate finger actuators", f"{side}_gripper_ctrl" in names and not any("_finger" in n for n in names)
              and int(m.actuator_trnid[m.actuator(f"{side}_gripper_ctrl").id, 0]) == fj[0].id)
    pj = m.joint("pedestal_joint")
    check("the pedestal is ONE slide joint, 0 to 0.418 m, with no other pedestal joint", pj.type[0] == mujoco.mjtJoint.mjJNT_SLIDE and np.allclose(pj.range, [0, 0.418])
          and not any(m.joint(i).name in ("MiddleBottom", "TopMiddle") for i in range(m.njnt)))

    print("\n3. masses, centres of mass, inertias")
    worst_m = worst_c = worst_i = 0.0
    finger_change = 0.0
    for key, lk in REF["links"].items():
        if "mass" not in lk or key.endswith("body_link0"):
            continue
        b = m.body(key)
        I_urdf = np.array([[lk["inertia"][0], lk["inertia"][3], lk["inertia"][4]], [lk["inertia"][3], lk["inertia"][1], lk["inertia"][5]], [lk["inertia"][4], lk["inertia"][5], lk["inertia"][2]]])
        Rq = np.zeros(9)
        mujoco.mju_quat2Mat(Rq, m.body_iquat[b.id])
        Rq = Rq.reshape(3, 3)
        I_m = Rq @ np.diag(m.body_inertia[b.id]) @ Rq.T
        worst_m = max(worst_m, abs(m.body_mass[b.id] - lk["mass"]))
        worst_c = max(worst_c, np.abs(m.body_ipos[b.id] - lk["com"]).max())
        if key.endswith("finger"):
            finger_change = max(finger_change, np.abs(np.linalg.eigvalsh(I_m) - np.linalg.eigvalsh(I_urdf)).max())
        else:
            worst_i = max(worst_i, np.abs(I_m - I_urdf).max())
    check("mass of every arm link, hand and finger equals the URDF's", worst_m < 1e-9, f"worst {worst_m:.1e} kg")
    check("centre of mass of each equals the URDF's", worst_c < 1e-8, f"worst {worst_c:.1e} m")
    check("inertia tensor of each arm link and hand equals the URDF's", worst_i < 1e-8, f"worst {worst_i:.1e} kg m^2")
    check("finger inertia: MuJoCo's balanced moments differ from the URDF's principal moments by under 3e-6 kg m^2 (the URDF's tensor, with products of inertia of 1e-6 on moments of 2.4e-6 "
          "and 7.5e-7, is not physical; a finger only slides, so this enters only the arm's total inertia, about 1e-3)", finger_change < 3e-6, f"{finger_change:.2e} kg m^2")
    lk7 = m.body("openarm_right_link7")
    check("the old right link7 centre of mass error is fixed (y = +0.01266, the mirror of the left's -0.01266)", abs(m.body_ipos[lk7.id][1] - 0.01266175) < 1e-6, f"y = {m.body_ipos[lk7.id][1]:.5f}")

    print("\n4. meshes (collision), including the mirrored ones")
    n_checked, n_mirrored, worst = 0, 0, 0.0
    for key, lk in REF["links"].items():
        if "collision" not in lk or key.endswith("body_link0"):
            continue
        b = m.body(key)
        gl = [g for g in range(m.ngeom) if m.geom_bodyid[g] == b.id and m.geom_group[g] == 3 and m.geom_type[g] == mujoco.mjtGeom.mjGEOM_MESH]
        if len(gl) != 1:
            check(f"{key}: one collision mesh geom", False, f"found {len(gl)}")
            continue
        g = gl[0]
        mid = m.geom_dataid[g]
        V = m.mesh_vert[m.mesh_vertadr[mid]:m.mesh_vertadr[mid] + m.mesh_vertnum[mid]].astype(float)
        got = d.geom_xpos[g] + V @ d.geom_xmat[g].reshape(3, 3).T
        sc, org = np.array(lk["collision"]["scale"]), np.array(lk["collision"]["origin"])
        exp = d.xpos[b.id] + (load_stl(stl_path(key)) * sc + org) @ d.xmat[b.id].reshape(3, 3).T
        err = max(np.abs(got.min(0) - exp.min(0)).max(), np.abs(got.max(0) - exp.max(0)).max(), np.abs(got.mean(0) - exp.mean(0)).max())
        worst = max(worst, err)
        n_checked += 1
        n_mirrored += sc[1] < 0
        if err > 2e-5:
            check(f"{key}: collision mesh placed as the URDF says (scale {sc[1] * 1000:+.0f})", False, f"error {err:.1e} m")
    check(f"all {n_checked} collision meshes ({n_mirrored} of them mirrored, scale y < 0) are where the URDF puts them", worst < 2e-5, f"worst {worst:.1e} m")
    tg = m.geom("openarm_body_link0_collision")
    print(f"  note: the torso's collision geom is '{m.mesh(m.geom_dataid[tg.id]).name}' (the narrow post), not the URDF's whole-torso mesh body_link0_symp (one convex hull over both shoulders)")

    print("\n5. pedestal")
    base, top = m.body("pedestal_base").id, m.body("pedestal_top").id
    check("the model starts raised: the joint's reference is 0.418", abs(m.qpos0[ped_adr] - 0.418) < 1e-12)
    for q, want in ((0.0, 0.3048), (0.418, 0.7228)):
        d.qpos[ped_adr] = q
        mujoco.mj_forward(m, d)
        z = d.xpos[torso][2] - d.xpos[base][2]
        check(f"torso {z:.4f} m above the pedestal base at q = {q}", abs(z - want) < 1e-9)
    check("mass of the fixed part 16.1868 kg and of the moving part 30.0476 kg (our old estimates)", abs(m.body_mass[base] - 16.1868) < 1e-9 and abs(m.body_mass[top] - 30.0476) < 1e-9,
          f"{m.body_mass[base]:.4f} and {m.body_mass[top]:.4f}")

    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
